"""
    Does a left binary circular shift on the number x of n_bits bits
    :param x: A number
    :param shift: The number of bits to shift
    :param n_bits: The number of bits of x
    :return: The shifted result
    """
def left_circ_shift(x: int, shift: int, n_bits: int) -> int {
    mask = (1 << n_bits) - 1;
    x_base = (x << shift) & mask;
    return (x_base | (x >> (n_bits - shift)));
}

""" Convert array of uint8_t into a single Python number """
def uint8array_to_number(uint8array: Any) -> object {
    return sum([(x << (i * 8)) for (i, x) in enumerate(uint8array)]);
}

